\begin{tikzpicture}[font=\sffamily, x=1.8cm, y=0.15cm, >=Stealth]
  \draw[->] (0,0) -- (3.5,0) node[right] {$t/\mathrm{s}$};
  \draw[->] (0,-12) -- (0,12) node[above] {$v/\mathrm{m\,s^{-1}}$};
  \foreach \t in {1,2,3} \draw (\t,0.6) -- (\t,-0.6) node[below=3pt] {\t};
  \foreach \v in {-10,-5,5,10} \draw (0.04,\v) -- (-0.04,\v) node[left] {\v};
  \node[below left] at (0,0) {0};
  \draw[thick] (0,0) -- (1,-10);
  \draw[thick] (1,-10) .. controls (1.3,-10) and (1.7,8) .. (2,8);
  \draw[thick] (2,8) -- (2.8,0);
  \fill (1,-10) circle (1.5pt) node[below left] {X};
  \fill (2,8) circle (1.5pt) node[above right] {Y};
  \fill (2.8,0) circle (1.5pt) node[above right] {Z};
  \node at (1.75,-17) {Fig. 1.1};
\end{tikzpicture}
